#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;
long long fact[2001], inv_[2001];
long long power(long long b, long long e) {
    long long r = 1; b %= MOD;
    while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
    return r;
}
long long choose(long long a, long long b) {
    if (!(0 <= b && b <= a)) return 0;
    return fact[a] * inv_[b] % MOD * inv_[a - b] % MOD;
}
// F(s,k) for every k: ways to split s into k parts in 1..n, by inclusion-exclusion.
vector<long long> parts(int s, int n) {
    vector<long long> out(s + 2, 0);
    for (int k = (s + n - 1) / n; k <= s; k++) {
        if (n == 1) out[k] = 1;
        else if (n == 2) out[k] = choose(k, s - k);
        else {
            long long value = 0;
            for (int j = 0; j <= (s - k) / n; j++) {
                long long term = choose(k, j) * choose(s - (long long)j * n - 1, k - 1) % MOD;
                value += (j % 2 == 0) ? term : -term;
            }
            out[k] = ((value % MOD) + MOD) % MOD;
        }
    }
    return out;
}
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    fact[0] = 1;
    for (int i = 1; i <= 2000; i++) fact[i] = fact[i - 1] * i % MOD;
    inv_[2000] = power(fact[2000], MOD - 2);
    for (int i = 2000; i > 0; i--) inv_[i - 1] = inv_[i] * i % MOD;
    int t; cin >> t;
    vector<array<int, 3>> cases;
    int p, c, n;
    while (cin >> p >> c >> n) cases.push_back({p, c, n});
    map<int, set<int>> needs;
    for (auto &[p, c, n] : cases) {
        if ((long long)p > (long long)n * (c + 1) || (long long)c > (long long)n * (p + 1) || n >= max(p, c)) continue;
        needs[n].insert(p); needs[n].insert(c);
    }
    map<pair<int, int>, vector<long long>> cache;
    for (auto &[n, totals] : needs) {
        int maximum = *totals.rbegin();
        // Estimate both algorithms' work before choosing one.
        long long inclusion = 0, cells = 0;
        for (int s : totals)
            for (int k = (s + n - 1) / n; k <= s; k++) inclusion += (s - k) / n + 1;
        for (long long k = 1; k <= maximum; k++) cells += min<long long>(maximum, n * k) - k + 1;
        if (n <= 2 || 5 * inclusion < cells) {
            for (int s : totals) cache[{s, n}] = parts(s, n);
            continue;
        }
        vector<pair<int, vector<long long> *>> targets;
        for (int s : totals) { auto &v = cache[{s, n}]; v.assign(s + 2, 0); targets.push_back({s, &v}); }
        vector<long long> previous(maximum + 1, 0), current(maximum + 1);
        previous[0] = 1;
        for (int k = 1; k <= maximum; k++) {
            fill(current.begin(), current.end(), 0);
            long long window = 0;
            int upper = (int)min<long long>(maximum, (long long)n * k);
            for (int s = k; s <= upper; s++) {
                window += previous[s - 1];
                if (s > n) window -= previous[s - n - 1];
                window = ((window % MOD) + MOD) % MOD;
                current[s] = window;
            }
            for (auto &[s, v] : targets)
                if (k <= s && s <= upper) (*v)[k] = current[s];
            swap(previous, current);
        }
    }
    string out;
    for (auto &[p, c, n] : cases) {
        long long answer;
        if ((long long)p > (long long)n * (c + 1) || (long long)c > (long long)n * (p + 1)) answer = 0;
        else if (n >= max(p, c)) answer = choose(p + c, p);
        else {
            const auto &a = cache[{p, n}], &b = cache[{c, n}];
            answer = 0;
            for (int k = 1; k <= min(p, c); k++)
                answer = (answer + 2 * a[k] % MOD * b[k] + a[k + 1] * b[k] % MOD + a[k] * b[k + 1] % MOD) % MOD;
        }
        out += to_string(answer); out += '\n';
    }
    cout << out;
}

