import (
	"bufio"
	"io"
	"os"
	"strconv"
	"sort"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

const MOD = 1000000007

var fact, inv [2001]int64

func power(b, e int64) int64 {
	r := int64(1)
	b %= MOD
	for e > 0 {
		if e&1 == 1 {
			r = r * b % MOD
		}
		b = b * b % MOD
		e >>= 1
	}
	return r
}

func choose(a, b int) int64 {
	if !(0 <= b && b <= a) {
		return 0
	}
	return fact[a] * inv[b] % MOD * inv[a-b] % MOD
}

// parts returns F(s,k) for every k: ways to split s into k parts in 1..n, by inclusion-exclusion.
func parts(s, n int) []int64 {
	out := make([]int64, s+2)
	for k := (s + n - 1) / n; k <= s; k++ {
		if n == 1 {
			out[k] = 1
		} else if n == 2 {
			out[k] = choose(k, s-k)
		} else {
			var value int64
			for j := 0; j <= (s-k)/n; j++ {
				term := choose(k, j) * choose(s-j*n-1, k-1) % MOD
				if j%2 == 0 {
					value += term
				} else {
					value -= term
				}
			}
			out[k] = (value%MOD + MOD) % MOD
		}
	}
	return out
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fact[0] = 1
	for i := 1; i <= 2000; i++ {
		fact[i] = fact[i-1] * int64(i) % MOD
	}
	inv[2000] = power(fact[2000], MOD-2)
	for i := 2000; i > 0; i-- {
		inv[i-1] = inv[i] * int64(i) % MOD
	}
	t := int(nextInt())
	cases := make([][3]int, t)
	for i := range cases {
		cases[i] = [3]int{int(nextInt()), int(nextInt()), int(nextInt())}
	}
	needs := map[int]map[int]bool{}
	for _, cs := range cases {
		p, c, n := cs[0], cs[1], cs[2]
		if p > n*(c+1) || c > n*(p+1) || n >= max(p, c) {
			continue
		}
		if needs[n] == nil {
			needs[n] = map[int]bool{}
		}
		needs[n][p] = true
		needs[n][c] = true
	}
	type key struct{ s, n int }
	cache := map[key][]int64{}
	for n, set := range needs {
		totals := make([]int, 0, len(set))
		for s := range set {
			totals = append(totals, s)
		}
		sort.Ints(totals)
		maximum := totals[len(totals)-1]
		// Estimate both algorithms' work before choosing one.
		var inclusion, cells int64
		for _, s := range totals {
			for k := (s + n - 1) / n; k <= s; k++ {
				inclusion += int64((s-k)/n + 1)
			}
		}
		for k := 1; k <= maximum; k++ {
			cells += int64(min(maximum, n*k) - k + 1)
		}
		if n <= 2 || 5*inclusion < cells {
			for _, s := range totals {
				cache[key{s, n}] = parts(s, n)
			}
			continue
		}
		targets := make([][]int64, len(totals))
		for i, s := range totals {
			targets[i] = make([]int64, s+2)
			cache[key{s, n}] = targets[i]
		}
		previous, current := make([]int64, maximum+1), make([]int64, maximum+1)
		previous[0] = 1
		for k := 1; k <= maximum; k++ {
			for i := range current {
				current[i] = 0
			}
			var window int64
			upper := min(maximum, n*k)
			for s := k; s <= upper; s++ {
				window += previous[s-1]
				if s > n {
					window -= previous[s-n-1]
				}
				window = (window%MOD + MOD) % MOD
				current[s] = window
			}
			for i, s := range totals {
				if k <= s && s <= upper {
					targets[i][k] = current[s]
				}
			}
			previous, current = current, previous
		}
	}
	for _, cs := range cases {
		p, c, n := cs[0], cs[1], cs[2]
		var answer int64
		if p > n*(c+1) || c > n*(p+1) {
			answer = 0
		} else if n >= max(p, c) {
			answer = choose(p+c, p)
		} else {
			a, b := cache[key{p, n}], cache[key{c, n}]
			for k := 1; k <= min(p, c); k++ {
				answer = (answer + 2*a[k]%MOD*b[k] + a[k+1]*b[k]%MOD + a[k]*b[k+1]%MOD) % MOD
			}
		}
		w.WriteString(strconv.FormatInt(answer, 10) + "\n")
	}
}
